char letterGrade(int score)
{
    if (score >= 90) return 'A';
    else if (score >= 80) return 'B';
    else if (score >= 70) return 'C';
    else if (score >= 60) return 'D';
    else return 'F';
}

unitTests:
TEST("top grades") { CHECK_EQ(letterGrade(95), 'A'); CHECK_EQ(letterGrade(90), 'A'); }
TEST("each boundary") { CHECK_EQ(letterGrade(89), 'B'); CHECK_EQ(letterGrade(80), 'B'); CHECK_EQ(letterGrade(79), 'C'); CHECK_EQ(letterGrade(70), 'C'); CHECK_EQ(letterGrade(69), 'D'); CHECK_EQ(letterGrade(60), 'D'); }
TEST("failing") { CHECK_EQ(letterGrade(59), 'F'); CHECK_EQ(letterGrade(0), 'F'); }

